(200, 'translations', '{\"uuid\":\"ededf699-cfea-4f7b-a1a3-60aead76d2b9\",\"displayName\":\"App\\\\Jobs\\\\TranslateChangesJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":null,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":null,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\TranslateChangesJob\",\"command\":\"O:28:\\\"App\\\\Jobs\\\\TranslateChangesJob\\\":8:{s:43:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000property_name\\\";s:8:\\\"question\\\";s:53:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000property_new_value_name\\\";s:42:\\\"Can I obtain a visa upon arrival in Egypt?\\\";s:46:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_name\\\";s:16:\\\"faq_translations\\\";s:50:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_fk_value\\\";i:1;s:49:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_fk_name\\\";s:6:\\\"faq_id\\\";s:36:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000locale\\\";s:2:\\\"es\\\";s:5:\\\"queue\\\";s:12:\\\"translations\\\";s:5:\\\"delay\\\";i:50;}\"}}', 0, NULL, 1753976340, 1753976290),
(201, 'translations', '{\"uuid\":\"849ec672-4beb-4478-836f-d6afc3f20c98\",\"displayName\":\"App\\\\Jobs\\\\TranslateChangesJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":null,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":null,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\TranslateChangesJob\",\"command\":\"O:28:\\\"App\\\\Jobs\\\\TranslateChangesJob\\\":8:{s:43:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000property_name\\\";s:6:\\\"answer\\\";s:53:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000property_new_value_name\\\";s:536:\\\"<p>Egypt visa arrival policy applies to the following countries: the United States, Australia, New Zealand, the United Kingdom, Canada, all European Union countries, Norway, Russia, Ukraine, Georgia, Serbia, Malaysia, Macedonia, Japan, South Korea, China (as of May 2018).<br><br>If you are a citizen of one of these countries, you can obtain a visa with your passport information, personal information, and details about your travel plans upon arrival at an Egyptian port of entry. The visa on arrival is usually valid for 30 days.<\\/p>\\\";s:46:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_name\\\";s:16:\\\"faq_translations\\\";s:50:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_fk_value\\\";i:1;s:49:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000model_table_fk_name\\\";s:6:\\\"faq_id\\\";s:36:\\\"\\u0000App\\\\Jobs\\\\TranslateChangesJob\\u0000locale\\\";s:2:\\\"fr\\\";s:5:\\\"queue\\\";s:12:\\\"translations\\\";s:5:\\\"delay\\\";i:60;}\"}}', 0, NULL, 1753976350, 1753976290),
