(406, 94, 'en', 'Day 9-Red Sea Riviera', '<div>\r\n<div class=\"flex gap-1 items-center\">&nbsp;</div>\r\n</div>\r\n<div class=\"flex flex-col gap-2 mt-3 md:mt-2 px-2 md:px-0\">\r\n<div class=\"flex flex-col gap-2 lg:block\">\r\n<p class=\"text-otg-neutrals-900  group-open:animate-fadeIn text-sm md:text-base\">Luxor - Hurghada. Departing Luxor we drive east to Hurghada, which is part of the beautiful Red Sea Riviera for 3 days on the beach!</p>\r\n</div>\r\n<div class=\"flex flex-col gap-1 pl-[4px] pt-2\">\r\n<div class=\"flex gap-1 items-center\"><span class=\"text-base md:text-lg text-otg-neutrals-900 font-semibold\">Overnight:</span><span class=\"text-base md:text-lg text-black font-normal\">Hurghada</span></div>\r\n<div class=\"flex gap-1 items-center\"><span class=\"text-base md:text-lg text-otg-neutrals-900 font-semibold\">Meals:</span><span class=\"text-base md:text-lg text-black font-normal\">Breakfast</span></div>\r\n</div>\r\n</div>'),
(407, 94, 'fr', NULL, NULL),
(408, 94, 'de', NULL, NULL),
