(2755, 524, 'de', NULL, NULL),
(2756, 524, 'it', NULL, NULL),
(2757, 524, 'pt', NULL, NULL),
(2758, 524, 'es', NULL, NULL),
(2759, 524, 'zh', NULL, NULL),
(2760, 525, 'en', 'CHECK OUT - FLY BACK TO CAIRO, FINAL DEPARTURE - WEDNESDAY,4TH OF AUGUST 2027', '<p>After breakfast, you will check out from your Hotel.<br>Catch our flight back to Cairo. catch your international flight.<br><br></p>'),
