(2767, 526, 'en', 'FREE DAY - Day 5 - TUESDAY,3RD OF AUGUST 2027', '<p>free day at leisure.<br>optional activities: Snorkeling, diving, desert safari.Overnight in Hurghada</p>'),
(2768, 526, 'fr', NULL, NULL),
(2769, 526, 'de', NULL, NULL),
