(2788, 529, 'en', 'FREE DAY - Day 2 - SATURDAY,31TH OF JULY 2027', '<p>After Breakfast, you will have free time to relax and enjoy the beautiful of the red sea at your leisure.<br><strong>Overnight in Hurghada.</strong><br><br></p>'),
(2789, 529, 'fr', NULL, NULL),
(2790, 529, 'de', NULL, NULL),
